#include "../src/hsd_scene.h"
#include "../src/training_stage.h"
#include <stdio.h>
#include <math.h>
static bool load(std::vector<unsigned char>& raw){FILE* f=fopen("C:\\Users\\luizf\\Documents\\melee_extraido\\MnSlMap.usd","rb");if(!f)return false;fseek(f,0,SEEK_END);long n=ftell(f);rewind(f);raw.resize(n);bool ok=fread(&raw[0],1,n,f)==(size_t)n;fclose(f);return ok;}
static void dump(Melee360Scene& scene,const char* path){FILE* fp=fopen(path,"wb");if(!fp)return;unsigned int n=(unsigned int)scene.textures.size();fwrite(&n,4,1,fp);for(unsigned int i=0;i<n;++i){Melee360SceneTexture& t=scene.textures[i];fwrite(&t.width,4,1,fp);fwrite(&t.height,4,1,fp);fwrite(&t.pixels[0],4,t.width*t.height,fp);}n=(unsigned int)scene.batches.size();fwrite(&n,4,1,fp);for(unsigned int i=0;i<n;++i){Melee360SceneBatch& b=scene.batches[i];unsigned int count=(unsigned int)b.vertices.size();fwrite(&b.texture,4,1,fp);fwrite(&b.mode,4,1,fp);fwrite(&b.wrapS,4,1,fp);fwrite(&b.wrapT,4,1,fp);fwrite(&count,4,1,fp);fwrite(&b.vertices[0],sizeof(Melee360SceneVertex),count,fp);}fclose(fp);}
int main(){std::vector<unsigned char> raw;if(!load(raw))return 1;Melee360StageInit();for(int stage=-1;stage<29;++stage){Melee360Scene scene;if(!Melee360LoadStageSelect(&raw[0],(unsigned int)raw.size(),60,0,0,stage,scene))return 2;if(stage==24){dump(scene,"stage-select-battlefield.bin");printf("SSS: %u batches, %u textures, skipped=%u\n",(unsigned int)scene.batches.size(),(unsigned int)scene.textures.size(),scene.skipped);}for(unsigned int b=0;b<scene.batches.size();++b)for(unsigned int v=0;v<scene.batches[b].vertices.size();++v)for(int c=0;c<4;++c)if(!_finite(scene.batches[b].vertices[v].clip[c]))return 3;}puts("Original SSS descriptors: all 29 previews and finite geometry passed");return 0;}
